mapper.select:
with lastdeal as ( SELECT tpa.portfolio_id portfolioId,/*组合代码*/ prd.finprod_id finprodId, max(TPD.SETTLE_DATE) payTaxVDate/*缴税/退税日期*/ FROM TRD_PRODUCT_DEAL TPD left join trd_product_deal_add tpa on tpd.trade_id = tpa.trade_id left join fin_product prd on tpd.finprod_id = prd.finprod_id left join PTL_PORTFOLIO ptl on tpa.portfolio_id = ptl.portfolio_id where TPD.BUSI_TYPE = #{BUSI_TYPE_16} and TPD.Finprod_Type = #{finprodType} and TPD.Finprod_Type2 = #{finprodType2} and TPD.CHL_ID is null /* add by jiangpeng on 20210510 end YHZGCPB20210115001 通道增值税缴纳*/ and not exists ( select 1 from TRD_PRODUCT_DEAL b where b.P_TRADE_ID = TPD.TRADE_ID )
and TPD.TRADE_STATUS = #{tradeStatus}
and TPD.PS = #{taxidenType}
group by TPD.PS, tpa.portfolio_id, ptl.PORTFOLIO_NAME, prd.finprod_id, prd.FINPROD_ABBR, tpd.ccy, TPD.TRADE_STATUS order by payTaxVDate,portfolioId desc ) select PORTFOLIO_ID portfolioId, /*组合代码*/ PORTFOLIO_NAME portfolioName, /*产品名称*/ profitType, FINPROD_ID finprodId,/*产品代码*/ FINPROD_MARKET_ID prodId,/*理财产品代码*/ FINPROD_ABBR finprodAbbr,/*产品简称*/ #{taxClass} taxClass, taxStartDate, /*缴税开始日*/ interestIncome, /*利息收入*/ dividendIncome, /*红利收入*/ difbetIncome, /*价差收入*/ (interestIncome + dividendIncome + difbetIncome) as appreciationTax, /*增值税*/ constructionTax, /*城建税*/ educationTax, /*教育费*/ placeeducationTax, /*地方教育费*/ waterTrafficTax, /*水利基金税*/ (constructionTax + educationTax + placeeducationTax + waterTrafficTax) as additionalTax, /*附加税*/ (interestIncome + dividendIncome + difbetIncome + constructionTax + educationTax + placeeducationTax + waterTrafficTax) taxTotal, /*税费总额*/ to_char(#{payment1},'yyyy')||'年'||trunc((to_char(#{payment1},'mm')+2)/3)||'季度销项税金结转金额:'|| to_char((interestIncome + dividendIncome + difbetIncome + constructionTax + educationTax + placeeducationTax + waterTrafficTax),'fm999990.9999') remark /*交易备注*/ from (select b.PORTFOLIO_ID, /*组合*/ c.PORTFOLIO_NAME, /*组合名称*/ c.profit_Type profitType, a.FINPROD_ID, a.FINPROD_ABBR, a.FINPROD_MARKET_ID, (select to_char(nvl(max(tpd.mdate + 1),a.vdate), 'yyyy-MM-dd') from TRD_PRODUCT_DEAL tpd left join BOK_DEAL_ACCOUNTING bda on tpd.trade_id = bda.busi_no where 1 = 1 and tpd.busi_type = #{BUSI_TYPE_16} and nvl(tpd.TRADE_STATUS,'01') = #{TRADE_STATUS_01} and tpd.mdate <= #{payment1} and tpd.finprod_id = a.finprod_id and tpd.CHL_ID is null /* add by jiangpeng on 20210510 end YHZGCPB20210115001 通道增值税缴纳*/ and not exists ( select 1 from TRD_PRODUCT_DEAL a1 where a1.p_trade_id = tpd.trade_id and a1.busi_type = tpd.busi_type and a1.TRADE_STATUS =#{TRADE_STATUS_03} ) ) as taxStartDate, /*modify by jiangpeng on 20210513 start ZGBSSE-387*/ nvl((select sum(bba.TDY_UNPAID_INTINCEXP) TDY_UNPAID_INTINCEXP from BOK_POSITION_PRDFEE bba where bba.FINPROD_ID = decode(c.profit_Type,#{profitType_SY},b.portfolio_id,b.finprod_id) and bba.CDATE = #{payment1} and bba.FEE_TYPE = #{TAX0102} and bba.chl_id is null), 0) as interestIncome, /*利息收入*/ nvl((select sum(bba.TDY_UNPAID_INTINCEXP) TDY_UNPAID_INTINCEXP from BOK_POSITION_PRDFEE bba where bba.FINPROD_ID = decode(c.profit_Type,#{profitType_SY},b.portfolio_id,b.finprod_id) and bba.CDATE = #{payment1} and bba.FEE_TYPE = #{TAX0202} and bba.chl_id is null), 0) as dividendIncome, /*红利收入*/ nvl((select sum(bba.TDY_UNPAID_INTINCEXP) TDY_UNPAID_INTINCEXP from BOK_POSITION_PRDFEE bba where bba.FINPROD_ID = decode(c.profit_Type,#{profitType_SY},b.portfolio_id,b.finprod_id) and bba.CDATE = #{payment1} and bba.FEE_TYPE = #{TAX0302} and bba.chl_id is null), 0) as difbetIncome, /*价差收入*/ nvl((select sum(bba.TDY_UNPAID_INTINCEXP) TDY_UNPAID_INTINCEXP from BOK_POSITION_PRDFEE bba where bba.FINPROD_ID = decode(c.profit_Type,#{profitType_SY},b.portfolio_id,b.finprod_id) and bba.CDATE = #{payment1} and bba.FEE_TYPE = #{ALT0102} and bba.chl_id is null), 0) as constructionTax, /*城建税*/ nvl((select sum(bba.TDY_UNPAID_INTINCEXP) TDY_UNPAID_INTINCEXP from BOK_POSITION_PRDFEE bba where bba.FINPROD_ID = decode(c.profit_Type,#{profitType_SY},b.portfolio_id,b.finprod_id) and bba.CDATE = #{payment1} and bba.FEE_TYPE = #{ALT0202} and bba.chl_id is null), 0) as educationTax, /*教育税*/ nvl((select sum(bba.TDY_UNPAID_INTINCEXP) TDY_UNPAID_INTINCEXP from BOK_POSITION_PRDFEE bba where bba.FINPROD_ID = decode(c.profit_Type,#{profitType_SY},b.portfolio_id,b.finprod_id) and bba.CDATE = #{payment1} and bba.FEE_TYPE = #{ALT0302} and bba.chl_id is null), 0) as placeeducationTax,/*地方教育费*/ nvl((select sum(bba.TDY_UNPAID_INTINCEXP) TDY_UNPAID_INTINCEXP from BOK_POSITION_PRDFEE bba where bba.FINPROD_ID = decode(c.profit_Type,#{profitType_SY},b.portfolio_id,b.finprod_id) and bba.CDATE = #{payment1} and bba.FEE_TYPE = #{ALT0402} and bba.chl_id is null), 0) as waterTrafficTax/*水利基金税*/ /*modify by jiangpeng on 20210513 end ZGBSSE-387*/ from FIN_PRODUCT a inner join FIN_PRODUCT_ADD b on a.FINPROD_ID = b.FINPROD_ID inner join PTL_PORTFOLIO c on b.portfolio_id = c.portfolio_id where 1 = 1 and a.FINPROD_TYPE2 = #{FINPROD_TYPE_F16} /*过滤已经缴纳税交易*/ and not exists ( select 1 from TRD_PRODUCT_DEAL b1 left join TRD_PRODUCT_DEAL c1 on b1.trade_id = c1.p_trade_id where b1.busi_type = #{BUSI_TYPE_16} and b1.FINPROD_ID = a.FINPROD_ID and b1.mdate = #{payment1} and c1.p_trade_id is null and b1.TRADE_STATUS =#{TRADE_STATUS_01} AND b1.CHL_ID is null/* add by jiangpeng on 20210510 end YHZGCPB20210115001 通道增值税缴纳*/ )
and b.portfolio_id in
#{item}
) where nvl(interestIncome + dividendIncome + difbetIncome,0) != 0 and PORTFOLIO_ID not in ( select lastDeal.portfolioId from lastDeal where lastDeal.payTaxVDate >= #{payment1})

select bbs.BOOKSET_ID as booksetId,bbs.BOOKSET_NAME booksetName from BOK_BOOKSET bbs left join BOK_BOOKSET_DATE BBD on BBD.BOOKSET_ID = bbs.BOOKSET_ID where 1=1
AND BBD.BOOKSET_ID IN
#{booksetId}
and BBD.BOOKSET_DATE > to_date(#{payment2}, 'yyyy-MM-dd')
and BBD.BOOKSET_DATE < to_date(#{payment1}, 'yyyy-MM-dd') +1
and (BBD.BOOKSET_ID IN ( select FINPROD_ID from FIN_PRODUCT_ADD where PORTFOLIO_ID in
#{item}
) or BBD.BOOKSET_ID IN
#{item}
)

select 
  T.CASH_ID cashId
  from  FIN_CASH_INFO T  
  WHERE T.FINPROD_ID =#{booksetId,jdbcType=VARCHAR}
  AND T.FINPROD_TYPE =#{acctsubjectType,jdbcType=VARCHAR}
  AND T.CASH_TYPE_2 = 'C07'

		select 
  			T.BOK_DETAIL_ID bokDetailid
 			 from BOK_DETAIL_ID T  
 			 WHERE T.BOOKSET_ID =#{booksetId,jdbcType=VARCHAR}
  			 AND T.BOK_DETAIL_ID = #{finprodId,jdbcType=VARCHAR}

SELECT TPD.PS taxidenType, /*类型*/ tpa.portfolio_id portfolioId,/*组合代码*/ ptl.PORTFOLIO_NAME portfolioName, /*组合名称*/ prd.finprod_id finprodId, prd.FINPROD_ABBR finprodAbbr, tpd.ccy ccy,/*币种*/ to_char(max(TPD.SETTLE_DATE), 'yyyy-MM-dd') payTaxVDate,/*缴税/退税日期*/ TPD.TRADE_STATUS tradeStatus FROM TRD_PRODUCT_DEAL TPD left join trd_product_deal_add tpa on tpd.trade_id = tpa.trade_id left join fin_product prd on tpd.finprod_id = prd.finprod_id left join fin_product prd1 on tpd.chl_id = prd1.finprod_id left join PTL_PORTFOLIO ptl on tpa.portfolio_id = ptl.portfolio_id where TPD.BUSI_TYPE = #{BUSI_TYPE_16} and TPD.Finprod_Type = #{finprodType} and TPD.Finprod_Type2 = #{finprodType2} and TPD.IS_CANCEL = #{IS_CANCEL} and not exists ( select 1 from TRD_PRODUCT_DEAL b where b.P_TRADE_ID = TPD.TRADE_ID )
and TPD.TRADE_STATUS = #{tradeStatus}
and prd1.finprod_market_id = #{channelId}
and TPD.chl_id is null
and tpa.portfolio_id in
#{item}
and TPD.PS = #{taxidenType}
group by TPD.PS, tpa.portfolio_id, ptl.PORTFOLIO_NAME, prd.finprod_id, prd.FINPROD_ABBR, tpd.ccy, TPD.TRADE_STATUS order by payTaxVDate,portfolioId desc

select distinct * from ( select case when bok.acct_subject_type = #{FINPROD_TYPE_F18} then ptl.portfolio_id when bok.acct_subject_type = #{FINPROD_TYPE_F16} then ad.portfolio_id else null end id, case when bok.acct_subject_type = #{FINPROD_TYPE_F18} then ptl.portfolio_name when bok.acct_subject_type = #{FINPROD_TYPE_F16} then (select ptl1.portfolio_name from ptl_portfolio ptl1 where ad.portfolio_id = ptl1.portfolio_id) else null end text from bok_position_prdfee fee left join bok_bookset bok on fee.finprod_id = bok.acct_subject_id left join fin_product fin on fee.chl_id = fin.finprod_id left join ptl_portfolio ptl on ptl.portfolio_id = fee.finprod_id left join fin_product_add ad on fee.finprod_id = ad.finprod_id where 1 = 1 and fee.cdate = to_date(#{payTaxMDate},'yyyy-mm-dd') and fin.finprod_market_id = #{channelId} and fee.tdy_unpaid_intincexp != 0 and fee.fee_type in (#{TAX0302}, #{TAX0202}, #{TAX0102}, #{ALT0102}, #{ALT0202}, #{ALT0302}, #{ALT0402})
and (ad.portfolio_id in
#{item}
or ptl.portfolio_id in
#{item}
)
) where id is not null and text is not null

  	 	select max(settle_date)
			  from TRD_PRODUCT_DEAL deal
			  left join fin_product
  				on deal.chl_id = fin_product.finprod_id
			 where deal.busi_type = #{BUSI_TYPE_16}
			   and fin_product.finprod_market_id = #{channelId}
			   and deal.ps = #{PS_C12}
			   and deal.is_cancel = #{YES_NO_NO}
			   and deal.trade_status = #{TRADE_STATUS_01}
